10	
11	/*!
12	 * \file loopbuf.h
13	 * \brief loopbuf api of AscendC
14	eg1：
15	    LoopBuffer<TPosition::VECIN, 2, 1024>  queIn;
16	
17	    LocalTensr<int> a;
18	    LocalTensr<float> b;
19	    LocalTensr<float> c;
20	
21	    queIn.AllocTensor(a, b);
22	    queIn.AllocTensor(c);
23	
24	    ...
25	    queIn.FreeTensor(a, b);
26	    queIn.FreeTensor(c);
27	 */
28	
29	#ifndef ATVOSS_LOOP_BUFFER_POOL_H
30	#define ATVOSS_LOOP_BUFFER_POOL_H
31	
32	namespace Atvoss {
33	
34	struct BufPoolCustom {
35	    uint64_t startAddr;
36	    uint64_t maxAddr;
37	    uint64_t maxLen;
38	};
39	
40	template <AscendC::TPosition src, AscendC::TPosition dst, int tileNum, int tileSize, bool useTPipe>
41	class LoopBufferEx {
42	private:
43	    static_assert(tileSize % 1024 == 0, "[ERROR]: [Atvoss][LoopBuffer] Tile must be a multiple of 1024\n");
44	    static_assert(tileNum >= 0 && tileNum <= 8, "[ERROR]: [Atvoss][LoopBuffer] TileNum must be [0, 8]\n");
45	
46	    static __aicore__ constexpr pipe_t ToPipe(AscendC::TPosition p)
47	    {
48	        if (p == AscendC::TPosition::VECIN) {
49	            return PIPE_MTE2;
50	        } else if (p == AscendC::TPosition::VECOUT) {
51	            return PIPE_MTE3;
52	        } else if (p == AscendC::TPosition::VECCALC) {
53	            return PIPE_V;
54	        }
55	    }
56	    static __aicore__ constexpr AscendC::HardEvent ToEvent()
57	    {
58	        if (src == AscendC::TPosition::VECIN && dst == AscendC::TPosition::VECCALC) {
59	            return AscendC::HardEvent::MTE2_V;
60	        } else if (src == AscendC::TPosition::VECIN && dst == AscendC::TPosition::VECOUT) {
61	            return AscendC::HardEvent::MTE2_MTE3;
62	        } else if (src == AscendC::TPosition::VECCALC && dst == AscendC::TPosition::VECOUT) {
63	            return AscendC::HardEvent::V_MTE3;
64	        }
65	        return AscendC::HardEvent::V_V;
66	    }
67	    static __aicore__ constexpr AscendC::HardEvent ToRevEvent()
68	    {
69	        if (src == AscendC::TPosition::VECIN && dst == AscendC::TPosition::VECCALC) {
70	            return AscendC::HardEvent::V_MTE2;
71	        } else if (src == AscendC::TPosition::VECIN && dst == AscendC::TPosition::VECOUT) {
72	            return AscendC::HardEvent::MTE3_MTE2;
73	        } else if (src == AscendC::TPosition::VECCALC && dst == AscendC::TPosition::VECOUT) {
74	            return AscendC::HardEvent::MTE3_V;
75	        }
76	        return AscendC::HardEvent::V_V;
77	    }
78	
79	public:
80	    __aicore__ inline LoopBufferEx()
81	    {}
82	    __aicore__ inline ~LoopBufferEx()
83	    {}
84	
85	    __aicore__ inline void DeInit()
86	    {
87	        for (uint8_t i = 0; i < tileNum; i++) {
88	            auto evtID = bufState_[i].evtID_;
89	            if (evtID >= 0) {
90	                wait_flag((pipe_t)ToPipe(dst), (pipe_t)ToPipe(src), evtID);
91	            }
92	        }
93	    }
94	    template <size_t baseAddr>
95	    __aicore__ inline void Init()
96	    {
97	        if constexpr (tileNum == 0) {
98	            return;
99	        }
100	        ASCENDC_ASSERT((baseAddr % 32 == 0), {
101	            KERNEL_LOG(KERNEL_ERROR, "[ERROR]: [Atvoss][LoopBuffer] InitBuffer bufferSize must be free state.");
102	        });
103	        bufPool_.startAddr = baseAddr;
104	        bufPool_.maxAddr = baseAddr + POOL_LEN;
105	        bufPool_.maxLen = POOL_LEN;
106	        if constexpr (useTPipe) {
107	            GetTPipePtr()->InitBuffer(tbuf_, POOL_LEN);
108	        }
109	        this->header_ = 0;
110	        for (int i = 0; i < tileNum; i++) {
111	#if defined(ASCENDC_CPU_DEBUG) && ASCENDC_CPU_DEBUG == 1
112	            bufState_[i].state_ = 0;
113	#endif
114	            bufState_[i].evtID_ = -1;
115	        }
116	    }
117	
118	    template <typename T, class... Args>
119	    __aicore__ inline void AllocTensor(AscendC::LocalTensor<T>& tensor, Args... args)
120	    {
121	        if constexpr (tileNum == 0) {
122	            return;
123	        }
124	        AscendC::TBuffAddr addr;
125	        addr.bufferAddr = bufPool_.startAddr + header_ * tileSize;
126	        addr.logicPos = (uint8_t)AscendC::TPosition::VECCALC;
127	        addr.bufferHandle = (AscendC::TBufHandle)header_;
128	        addr.dataLen = tileSize;
129	        if constexpr (ToRevEvent() != AscendC::HardEvent::V_V) {
130	            if (bufState_[header_].evtID_ >= 0) {
131	                auto evtID = bufState_[header_].evtID_;
132	                wait_flag((pipe_t)ToPipe(dst), (pipe_t)ToPipe(src), evtID);
133	                if constexpr (useTPipe) {
134	                    GetTPipePtr()->ReleaseEventID<ToRevEvent()>(evtID);
135	                }
136	                bufState_[header_].evtID_ = -1;
137	            }
138	        }
139	
140	#if defined(ASCENDC_CPU_DEBUG) && ASCENDC_CPU_DEBUG == 1
141	        ASCENDC_ASSERT((bufState_[header_].state_ == 0), {
142	            KERNEL_LOG(KERNEL_ERROR, "[ERROR]: [Atvoss][LoopBuffer] buffer must be free state.");
143	        });
144	        bufState_[header_].state_ = 1;
145	        AscendC::LocalTensor<uint32_t> tmpTensor = tbuf_.Get<uint32_t>();
146	        addr.absAddr = reinterpret_cast<uint8_t*>(tmpTensor.GetPhyAddr() + header_ * tileSize);
147	#endif
148	
149	        if (++header_ >= tileNum) {
150	            header_ = 0;
151	        }
152	        tensor.SetAddr(addr);
153	        if constexpr (sizeof...(args) > 0) {
154	            AllocTensor(args...);
155	        }
156	    }
157	    template <typename T, class... Args>
158	    __aicore__ inline void FreeTensor(T& tensor, Args... args)
159	    {
160	        auto bufPos = static_cast<uint8_t>(reinterpret_cast<uintptr_t>(tensor.GetBufferHandle()));
161	        if constexpr (tileNum == 0) {
162	            return;
163	        }
164	        if constexpr (ToRevEvent() != AscendC::HardEvent::V_V) {
165	            auto evtID = 0;
166	            if constexpr (useTPipe) {
167	                evtID = GetTPipePtr()->AllocEventID<ToRevEvent()>();
168	            } else {
169	                eventID_ = eventID_ ^ 1;
170	                evtID = eventID_;
171	            }
172	            bufState_[bufPos].evtID_ = evtID;
173	            set_flag((pipe_t)ToPipe(dst), (pipe_t)ToPipe(src), evtID);
174	        }
175	
176	#if defined(ASCENDC_CPU_DEBUG) && ASCENDC_CPU_DEBUG == 1
177	        ASCENDC_ASSERT((bufPos >= 0 && bufPos < tileNum), { KERNEL_LOG(KERNEL_ERROR, ""); });
178	        ASCENDC_ASSERT((bufState_[bufPos].state_ == 1), {
179	            KERNEL_LOG(KERNEL_ERROR, "[ERROR]: [Atvoss][LoopBuffer] buffer must be alloc state.");
180	        });
181	        bufState_[bufPos].state_ = 0;
182	#endif
183	        if constexpr (sizeof...(args) > 0) {
184	            FreeTensor(args...);
185	        }
186	    }
187	
188	    static __aicore__ inline void Sync()
189	    {
190	        if constexpr (ToEvent() != AscendC::HardEvent::V_V) {
191	            auto evtID = 7;
192	            if constexpr (useTPipe) {
193	                evtID = GetTPipePtr()->FetchEventID<ToEvent()>();
194	            }
195	            set_flag((pipe_t)ToPipe(src), (pipe_t)ToPipe(dst), evtID);
196	            wait_flag((pipe_t)ToPipe(src), (pipe_t)ToPipe(dst), evtID);
197	        }
198	    }
199	
200	private:
201	    int8_t eventID_ = 6;
202	    BufPoolCustom bufPool_;
203	    AscendC::TBuf<AscendC::TPosition::VECCALC> tbuf_;
204	    static constexpr uint64_t POOL_LEN = tileSize * tileNum;
205	    uint8_t header_;
206	    struct BufState {
207	#if defined(ASCENDC_CPU_DEBUG) && ASCENDC_CPU_DEBUG == 1
208	        uint8_t state_;
209	#endif
210	        int8_t evtID_;
211	    } bufState_[tileNum];
212	};
213	
214	template <AscendC::TPosition pos, int tileNum, int tileSize, bool useTPipe = false>
215	class LoopBuffer {};
216	
217	template <int tileNum, int tileSize, bool useTPipe>
218	class LoopBuffer<AscendC::TPosition::VECIN, tileNum, tileSize, useTPipe>
219	    : public LoopBufferEx<AscendC::TPosition::VECIN, AscendC::TPosition::VECCALC, tileNum, tileSize, useTPipe> {};
220	template <int tileNum, int tileSize, bool useTPipe>
221	class LoopBuffer<AscendC::TPosition::VECOUT, tileNum, tileSize, useTPipe>
222	    : public LoopBufferEx<AscendC::TPosition::VECCALC, AscendC::TPosition::VECOUT, tileNum, tileSize, useTPipe> {};
223	template <int tileNum, int tileSize, bool useTPipe>
224	class LoopBuffer<AscendC::TPosition::VECCALC, tileNum, tileSize, useTPipe>
225	    : public LoopBufferEx<AscendC::TPosition::VECCALC, AscendC::TPosition::VECCALC, tileNum, tileSize, useTPipe> {};
226	} // namespace Atvoss
227	
228	#endif // ATVOSS_LOOP_BUFFER_POOL_H

