486	    // release & update
487	    using PersistMte2Lst = typename BufLsts::PersistMte2Lst;
488	    using Mte2LstNext = Concatenate_t<
489	        typename BufLsts::Mte2Lst, typename ReleaseBufferByUsage<OpLst, ToReleaseLst, opPos, BUF_MTE2, cacheBrc>::Type>;
490	    using PersistMte3Lst = typename BufLsts::PersistMte3Lst;
491	    using Mte3LstNext = Concatenate_t<
492	        typename BufLsts::Mte3Lst, typename ReleaseBufferByUsage<OpLst, ToReleaseLst, opPos, BUF_MTE3, cacheBrc>::Type>;
493	    using PersistTmpLst = typename BufLsts::PersistTmpLst;
494	    using TmpLstNext = Concatenate_t<
495	        typename BufLsts::TmpLst, typename ReleaseBufferByUsage<OpLst, ToReleaseLst, opPos, BUF_TEMP, cacheBrc>::Type>;
496	    using PongMte3LstNext = Concatenate_t<
497	        typename BufLsts::PongMte3Lst,
498	        typename ReleaseBufferByUsage<OpLst, ToReleaseLst, opPos, BUF_MTE3, cacheBrc, BUF_PONG>::Type>;
499	    // update ToReleaseLst to speedup next release
500	    using ToReleaseLstNext = typename ReleaseUnusedInput<OpLst, ToReleaseLst, opPos, cacheBrc>::Type;
501	
502	public:
503	    using Type = TypeList<
504	        PersistMte2Lst, Mte2LstNext, PersistMte3Lst, Mte3LstNext, PersistTmpLst, TmpLstNext, PongMte3LstNext,
505	        ToReleaseLstNext>;
506	};
507	
508	#if !defined(__ATVOSS_HOST_ONLY__)
509	template <typename TL, std::size_t N, BufType bt, int start = 0>
510	__aicore__ auto GetBufferId(bool isPing = true)
511	{
512	    if constexpr (start < Size_v<TL>) {
513	        using bufMap = Get_t<TL, start>;
514	        if constexpr (bufMap::paramNum == N && bufMap::bufType == bt) {
515	            return isPing ? bufMap::pingBufId : bufMap::pongBufId;
516	        } else {
517	            return GetBufferId<TL, N, bt, start + 1>(isPing);
518	        }
519	    } else {
520	        static_assert(start < Size_v<TL>, "Param or LocalVar Id invalid.");
521	    }
522	};
523	#endif
524	
525	/*
526	 * Generate buffer id of each Expression savedin @OpLst as per @memLvl
527	 * Template Arguments：
528	 *   1. OpLst: Ordered full Expression / Compute list
529	 *   2. OutLst: Full list of Output
530	 *   3. BufLstLst：Unused MTE2/MTE3/TmpBuffer List
531	 *   4. pongOffset: Offset of Pong buffer id to Ping buffer
532	 *   5. memLvl: memory level (policy) 0/1/2
533	 *   6. useNddma: whether use NDDMA from CopyInBrc operator
534	 *   7. cacheBrc: whether cache CopyInBrc & VecBrc operation outputs
535	 *   8. AllocLst: Allocated buffer list of `BufferWrapper` currently
536	 *   9. ToReleaseLst: To release list of `Mapping<Bind, TypeList<BufferWrapper...>>`
537	 *  10. scalarIdx: index or placehold of next `Scalar` operation output
538	 *  11. opPos: Position of current Expression / Compute
539	 * Return：
540	 *   1. 2*Size_v<OpLst> integer matrix as `const int32_t* const*`
541	 */
542	template <
543	    typename OpLst, typename OutLst, typename BufLstLst, uint32_t pongOffset, MemLevel memLvl = MemLevel::LEVEL_2,
544	    bool useNddma = true, bool cacheBrc = false, typename AllocLst = TypeList<>, typename ToReleaseLst = TypeList<>,
545	#ifdef __ATP_UT__
546	    int32_t scalarIdx = 50,
547	#else
548	    int32_t scalarIdx = 0,
549	#endif
550	    std::size_t opPos = 0>
551	static constexpr const int32_t* const* GenerateBufferIdOrder()
552	{
553	    if constexpr (opPos < Size_v<OpLst>) {
554	        using Op = Get_t<OpLst, opPos>;
555	        if constexpr (Op::isScalarOp) {
556	            using Buf = BufferWrapper<scalarIdx, BUF_SCALAR>;
557	            using AllocLstNext = Append_t<AllocLst, Buf>;
558	            return GenerateBufferIdOrder<
559	                OpLst, OutLst, BufLstLst, pongOffset, memLvl, useNddma, cacheBrc, AllocLstNext, ToReleaseLst,
560	                scalarIdx + 1, opPos + 1>();
561	        } else if constexpr (false /*IsBindOfOp_v<OpCopyInBrc, Op>*/ && !useNddma) { // TODO
562	            // use copyIn + ubBrc to implement nddma.
563	            using NextLst0 = AllocMte2_t<BufLstLst, memLvl, cacheBrc>;
564	            using Mte2 = Get_t<NextLst0, BUF_ALLOCATED_IDX>;
565	            if constexpr (ConnectToAny_v<OutLst, Op>) {
566	                // if CopyInBrc -> CopyOut, should use MTE3
567	                using NextLst = AllocMte3_t<NextLst0, memLvl, cacheBrc>;
568	                using Mte3 = Get_t<NextLst, BUF_ALLOCATED_IDX>;
569	                // add to alloc list
570	                using Buf = CombinedBufferWrappers<Mte3, Mte2>;
571	                using AllocLstNext = Append_t<AllocLst, Buf>;
572	                using ToReleaseLstNext = Append_t<ToReleaseLst, Mapping<Op, Mte3, Mte2>>;
573	                // next
574	                return GenerateBufferIdOrder<
575	                    OpLst, OutLst, NextLst, pongOffset, memLvl, useNddma, cacheBrc, AllocLstNext, ToReleaseLstNext,
576	                    scalarIdx, opPos + 1>();
577	            } else {
578	                using NextLst = AllocTempBuffer_t<NextLst0, memLvl, cacheBrc>;
579	                using Tmp = Get_t<NextLst, BUF_ALLOCATED_IDX>;
580	                // add to alloc list
581	                using Buf = CombinedBufferWrappers<Tmp, Mte2>;
582	                using AllocLstNext = Append_t<AllocLst, Buf>;
583	                using ToReleaseLstNext = Append_t<ToReleaseLst, Mapping<Op, Tmp, Mte2>>;
584	                // next
585	                return GenerateBufferIdOrder<
586	                    OpLst, OutLst, NextLst, pongOffset, memLvl, useNddma, cacheBrc, AllocLstNext, ToReleaseLstNext,
587	                    scalarIdx, opPos + 1>();
588	            }
589	        } else if constexpr (IsBindOfOp_v<OpCopyIn, Op>) {
590	            // activate cache when CopyInBrc = NDDMA
591	            using NextLst = AllocMte2_t<BufLstLst, memLvl, IsCacheBind_v<cacheBrc, Op>>;
592	            using Mte2 = Get_t<NextLst, BUF_ALLOCATED_IDX>;
593	            // add to alloc list
594	            using AllocLstNext = Append_t<AllocLst, Mte2>;
595	            using ToReleaseLstNext = Append_t<ToReleaseLst, Mapping<Op, Mte2>>;
596	            // next
597	            return GenerateBufferIdOrder<
598	                OpLst, OutLst, NextLst, pongOffset, memLvl, useNddma, cacheBrc, AllocLstNext, ToReleaseLstNext,
599	                scalarIdx, opPos + 1>();
600	        } else if constexpr (IsBindOfOp_v<OpCopyOut, Op>) {
601	            using NextLst = typename ReleaseAndUpdateLst<OpLst, BufLstLst, ToReleaseLst, cacheBrc, opPos>::Type;
602	            // release and update
603	            using ToReleaseLstNext = Get_t<NextLst, BUF_TO_RELEASE_IDX>;
604	            // fill -1 when no buffer is needed.
605	            using Buf = BufferWrapper<-1, BUF_PLACEHOLDER>;
606	            using AllocLstNext = Append_t<AllocLst, Buf>;
607	            // next
608	            return GenerateBufferIdOrder<
609	                OpLst, OutLst, NextLst, pongOffset, memLvl, useNddma, cacheBrc, AllocLstNext, ToReleaseLstNext,
610	                scalarIdx, opPos + 1>();
611	        } else {
612	            if constexpr (ConnectToAny_v<OutLst, Op>) {
613	                // activate cache when current Node is VecBrc
614	                using NextLst0 = AllocMte3_t<BufLstLst, memLvl, IsCacheBind_v<cacheBrc, Op>>;
615	                using Mte3 = Get_t<NextLst0, BUF_ALLOCATED_IDX>;
616	                // add to alloc list
617	                using AllocLstNext = Append_t<AllocLst, Mte3>;
618	                // release and update
619	                using NextLst = typename ReleaseAndUpdateLst<OpLst, NextLst0, ToReleaseLst, cacheBrc, opPos>::Type;
620	                using ToReleaseLstNext = Append_t<Get_t<NextLst, BUF_TO_RELEASE_IDX>, Mapping<Op, Mte3>>;
621	                // next
622	                return GenerateBufferIdOrder<
623	                    OpLst, OutLst, NextLst, pongOffset, memLvl, useNddma, cacheBrc, AllocLstNext, ToReleaseLstNext,
624	                    scalarIdx, opPos + 1>();
625	            } else {
626	                // activate cache when current Node is VecBrc
627	                using NextLst0 = AllocTempBuffer_t<BufLstLst, memLvl, IsCacheBind_v<cacheBrc, Op>>;
628	                using Tmp = Get_t<NextLst0, BUF_ALLOCATED_IDX>;
629	                // add to alloc list
630	                using AllocLstNext = Append_t<AllocLst, Tmp>;
631	                // release and update
632	                using NextLst = typename ReleaseAndUpdateLst<OpLst, NextLst0, ToReleaseLst, cacheBrc, opPos>::Type;
633	                using ToReleaseLstNext = Append_t<Get_t<NextLst, BUF_TO_RELEASE_IDX>, Mapping<Op, Tmp>>;
634	                // next
635	                return GenerateBufferIdOrder<
636	                    OpLst, OutLst, NextLst, pongOffset, memLvl, useNddma, cacheBrc, AllocLstNext, ToReleaseLstNext,
637	                    scalarIdx, opPos + 1>();
638	            }
639	        }
640	    } else {
641	        // generate buffer id list for ping-pong as per AllocLst.
642	        static_assert(Size_v<OpLst> == Size_v<AllocLst>, "Size_v<OpLst> == Size_v<AllocLst>");
643	        return ExtractBufferId<AllocLst, pongOffset>::Value;
644	    }
645	}
646	
647	} // namespace Atvoss::Ele::Tile
648	#endif // ATVOSS_ELEWISE_GRAPH_BUFFER_H

