149	        if constexpr (!std::is_scalar_v<typename ParamType::Type>) {
150	            using DType = typename ParamType::Type::PrimType;
151	            if (defaultSize < sizeof(DType)) {
152	                defaultSize = sizeof(DType);
153	            }
154	        }
155	
156	        constexpr int len = Size_v<Params>;
157	        if constexpr (N < len - 1) {
158	            return FindParamsMaxTypeSizeImpl<N + 1, Params>(defaultSize);
159	        }
160	        return defaultSize;
161	    }
162	
163	    template <typename Params>
164	    static constexpr uint32_t FindParamsMaxTypeSize()
165	    {
166	        return FindParamsMaxTypeSizeImpl<0, Params>();
167	    }
168	
169	    static constexpr uint32_t MaxSize = FindParamsMaxTypeSize<Params>();
170	
171	    /*!
172	     * \brief Get the size of UB space occupied by a single node during compilation.
173	     * \return uint32_t. Maximum number of elements allocated in a single node.
174	     */
175	    static constexpr uint32_t GetEleCntInTensor()
176	    {
177	        if constexpr (ShapeSize::value == 2) {
178	            using DstShape1Type = typename ShapeT::template get_type<1>;
179	            return ((UB_TILE_SIZE / MaxSize) + DstShape1Type::value - 1) / DstShape1Type::value;
180	        }
181	        return ((UB_TILE_SIZE / MaxSize) + ALIGNMENT - 1) / ALIGNMENT;
182	    }
183	
184	    static constexpr uint32_t ELEMENT_COUNT_IN_TENSOR = GetEleCntInTensor();
185	    /* ----------------Calc element count in a tensor end---------------- */
186	
187	public:
