289	    template <typename Params, typename ArgTup, std::size_t... Ints>
290	    __aicore__ inline constexpr auto PrepareBlockParamsImpl(ArgTup& args, AscendC::Std::index_sequence<Ints...>)
291	    {
292	        return AscendC::Std::make_tuple(ConstructBlockParam<Get_t<Params, Ints>>(args)...);
293	    }
